import{d as g,C as e,o as u,c as h,a3 as i,E as a,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·泰伯","description":"《论语》第 8 篇「泰伯」——二十一章原文与导读。至德、曾子临终之言、士不可以不弘毅、兴于诗立于礼成于乐、大哉尧之为君。","frontmatter":{"title":"论语·泰伯","description":"《论语》第 8 篇「泰伯」——二十一章原文与导读。至德、曾子临终之言、士不可以不弘毅、兴于诗立于礼成于乐、大哉尧之为君。","category":"guide","aliases":["泰伯","泰伯篇","泰伯第八","论语泰伯","lunyu 泰伯"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-08.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-08.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/lunyu/chapter-08.md"},x=g({...m,setup(y){const s=[{id:"yi",label:"一、泰伯其可谓至德也已矣",showLabel:!0,sentences:[["子曰：“泰伯，其可谓",{text:"至德",glossary:"zhide"},"也已矣。三以天下让，民无得而称焉。”"]],note:"孔子赞泰伯：「其可谓至德也已矣」——可说是至德了。「三以天下让，民无得而称焉」——三次把天下让给弟弟（季历），而百姓却找不出具体事迹来称颂他（因其让得无迹可寻）。"},{id:"er",label:"二、恭而无礼则劳",showLabel:!0,sentences:[["子曰：“恭而无礼则劳；慎而无礼则",{text:"葸",glossary:"xi-ju"},"；勇而无礼则乱；直而无礼则",{text:"绞",glossary:"jiao"},"。君子",{text:"笃于亲",glossary:"duyuqin"},"，则民兴于仁；",{text:"故旧不遗",glossary:"gujiubuyi"},"，则民不",{text:"偷",glossary:"tou"},"。”"]],note:"「恭而无礼则劳；慎而无礼则葸；勇而无礼则乱；直而无礼则绞」——恭敬而无礼则徒劳，谨慎而无礼则畏缩（葸＝畏怯），勇敢而无礼则作乱，直率而无礼则尖刻（绞＝急切刺人）。四句皆言礼之为节文。「君子笃于亲，则民兴于仁；故旧不遗，则民不偷」——在上者厚待亲族，百姓便趋于仁；不遗弃故旧，民风便不浇薄。"},{id:"san",label:"三、启予足，启予手",showLabel:!0,sentences:[["曾子有疾，召门弟子曰：“",{text:"启予足",glossary:"qiyuzu"},"，启予手。《诗》云：‘战战兢兢，如临深渊，如履薄冰。’而今而后，吾知免夫，小子！”"]],note:"曾子病重，召门弟子曰：「启予足，启予手」——看看我的脚，看看我的手（谓身未毁伤）。引《诗》「战战兢兢，如临深渊，如履薄冰」。「而今而后，吾知免夫，小子」——从今以后，我知道可以免于毁伤了，小子们！（曾子以「身体发肤受之父母，不敢毁伤」为孝。）"},{id:"si",label:"四、鸟之将死，其鸣也哀",showLabel:!0,sentences:[["曾子有疾，孟敬子问之。曾子言曰：“鸟之将死，其鸣也哀；人之将死，其言也善。君子所贵乎道者三：动容貌，斯远",{text:"暴慢",glossary:"baoman"},"矣；正颜色，斯近信矣；出辞气，斯远",{text:"鄙倍",glossary:"bibi"},"矣。",{text:"笾豆之事",glossary:"biandou"},"，则有司存。”"]],note:"曾子病重，孟敬子来问。曾子说：「鸟之将死，其鸣也哀；人之将死，其言也善」。「君子所贵乎道者三：动容貌，斯远暴慢矣」（举止容貌端正，便远离粗暴怠慢）；「正颜色，斯近信矣」（脸色端庄，便近乎诚信）；「出辞气，斯远鄙倍矣」（言辞声气得体，便远离鄙陋背理）。末句「笾豆之事，则有司存」——至于祭器陈设等具体事务，自有主管者在。"},{id:"wu",label:"五、以能问于不能",showLabel:!0,sentences:[["曾子曰：“以能问于不能；以多问于寡；有若无，实若虚，",{text:"犯而不校",glossary:"fanerbuliao"},"。昔者吾友尝从事于斯矣。”"]],note:"曾子说：「以能问于不能；以多问于寡；有若无，实若虚，犯而不校」——有才能的向无才能者请教，知识多的向知识少者请教，有像没有，实像虚，被冒犯也不计较。「昔者吾友尝从事于斯矣」——从前我的朋友（指颜回）曾致力于此。"},{id:"liu",label:"六、可以托六尺之孤",showLabel:!0,sentences:[["曾子曰：“可以托六尺之孤，可以寄百里之命，临大节而不可夺也。君子人与？君子人也。”"]],note:"曾子说：「可以托六尺之孤」——可以把幼小的孤儿托付给他；「可以寄百里之命」——可以把方圆百里的国政托付给他；「临大节而不可夺也」——面对重大关头而不能使他动摇。「君子人与？君子人也」——这是君子吗？是君子啊。"},{id:"qi",label:"七、士不可以不弘毅",showLabel:!0,sentences:[["曾子曰：“士不可以不",{text:"弘毅",glossary:"hongyi"},"，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？”"]],note:"曾子说：「士不可以不弘毅，任重而道远」——士人不可以不宏大刚毅，因为责任重而道路远。「仁以为己任，不亦重乎？死而后已，不亦远乎」——把「仁」担作自己的责任，不也很重吗？至死方止，不也很远吗？"},{id:"ba",label:"八、兴于诗，立于礼，成于乐",showLabel:!0,sentences:[["子曰：“兴于《诗》，立于礼，成于乐。”"]],note:"「兴于《诗》，立于礼，成于乐」——由《诗》感发志意而兴起，由礼而立身处世，由乐而完成涵养。三句为为学之三个阶段。"},{id:"jiu",label:"九、民可使由之",showLabel:!0,sentences:[["子曰：“民可使由之，不可使知之。”"]],note:"「民可使由之，不可使知之」——百姓可以让他们照着去做，不可以让他们知道其所以然。（此章异解甚多，一说当读作「民可，使由之；不可，使知之」。）"},{id:"shi",label:"十、好勇疾贫",showLabel:!0,sentences:[["子曰：“好勇疾贫，乱也。人而不仁，疾之已甚，乱也。”"]],note:"「好勇疾贫，乱也」——好勇而厌恨贫穷，就会作乱；「人而不仁，疾之已甚，乱也」——对于不仁之人，痛恨得太过分，也会生乱。"},{id:"shiyi",label:"十一、使骄且吝",showLabel:!0,sentences:[["子曰：“如有周公之才之美，使骄且",{text:"吝",glossary:"lin"},"，其余不足观也已。”"]],note:"「如有周公之才之美，使骄且吝，其余不足观也已」——纵有周公那样的才能与美质，只要既骄傲又吝啬，其余也就不值一看了。"},{id:"shier",label:"十二、三年学，不至于谷",showLabel:!0,sentences:[["子曰：“三年学，不至于",{text:"谷",glossary:"gu-lu"},"，不易得也。”"]],note:"「三年学，不至于谷，不易得也」——学了三年而不想到俸禄（谷＝俸禄），这是很难得的。"},{id:"shisan",label:"十三、危邦不入，乱邦不居",showLabel:!0,sentences:[["子曰：“笃信好学，守死善道。危邦不入，乱邦不居。天下有道则见，无道则隐。邦有道，贫且贱焉，耻也；邦无道，富且贵焉，耻也。”"]],note:"「笃信好学，守死善道」——笃于信、好于学，守节至死而不失善道。「危邦不入，乱邦不居」——危乱之国不进入、不居留。「天下有道则见（现），无道则隐」——天下有道便出仕，无道便隐退。「邦有道，贫且贱焉，耻也；邦无道，富且贵焉，耻也」——国有道而自己贫贱是耻，国无道而自己富贵也是耻。"},{id:"shisi",label:"十四、不在其位，不谋其政",showLabel:!0,sentences:[["子曰：“不在其位，不谋其政。”"]],note:"「不在其位，不谋其政」——不在那个职位上，便不谋划那个职位的政事。"},{id:"shiwu",label:"十五、洋洋乎盈耳哉",showLabel:!0,sentences:[["子曰：“师挚之始，《关雎》之乱，",{text:"洋洋乎",glossary:"yangyanghu"},"盈耳哉！”"]],note:"「师挚之始，《关雎》之乱，洋洋乎盈耳哉」——自乐师挚开始演奏（升歌），到《关雎》末章合乐（乱＝乐之卒章），美盛的乐声充盈于耳啊！写孔子听乐之感。"},{id:"shiliu",label:"十六、吾不知之矣",showLabel:!0,sentences:[["子曰：“狂而不直，",{text:"侗",glossary:"tong"},"而不愿，",{text:"悾悾",glossary:"kongkong"},"而不信，吾不知之矣。”"]],note:"「狂而不直，侗而不愿，悾悾而不信，吾不知之矣」——狂放而不正直，无知而不谨厚（侗＝无知，愿＝谨厚），诚恳而不守信（悾悾＝诚恳貌）：对这样的人，我真不知如何是好。"},{id:"shiqi",label:"十七、学如不及",showLabel:!0,sentences:[["子曰：“学如不及，犹恐失之。”"]],note:"「学如不及，犹恐失之」——为学就像追赶而总赶不上，赶上了还怕丢掉。写为学之勤与惧。"},{id:"shiba",label:"十八、巍巍乎，舜禹之有天下也",showLabel:!0,sentences:[["子曰：“巍巍乎！舜、禹之有天下也而不与焉。”"]],note:"「巍巍乎！舜、禹之有天下也而不与焉」——崇高啊！舜、禹拥有天下却不以天下为己有（不与＝不参与其间、不以为己有）。写其公天下之心。"},{id:"shijiu",label:"十九、大哉尧之为君也",showLabel:!0,sentences:[["子曰：“大哉尧之为君也！巍巍乎，唯天为大，唯尧则之。",{text:"荡荡乎",glossary:"dangdanghu"},"，民无能名焉。巍巍乎其有成功也，焕乎其有文章！”"]],note:"「大哉尧之为君也！巍巍乎，唯天为大，唯尧则之」——伟大啊尧之为君！崇高啊，唯天最大，唯尧能效法天。「荡荡乎，民无能名焉」——广大啊，百姓无法以言语称说。「巍巍乎其有成功也，焕乎其有文章」——崇高啊他的功业，光辉啊他的礼乐制度。"},{id:"ershi",label:"二十、才难，不其然乎",showLabel:!0,sentences:[["舜有臣五人而天下治。武王曰：“予有乱臣十人。”孔子曰：“才难，不其然乎？唐虞之际，于斯为盛；有妇人焉，九人而已。三分天下有其二，以服事殷。周之德，其可谓至德也已矣。”"]],note:"舜有臣五人而天下治；武王曰「予有乱臣十人」（我有治乱之臣十人）。孔子说：「才难，不其然乎」——人才难得，不正是这样吗？「唐虞之际，于斯为盛；有妇人焉，九人而已」——唐虞之际人才最盛；然十人中有一位是妇人，只算九人。「三分天下有其二，以服事殷。周之德，其可谓至德也已矣」——周文王已得天下三分之二，仍服事殷商——周之德，可说是至德了。"},{id:"ershiyi",label:"二十一、禹，吾无间然矣",showLabel:!0,sentences:[["子曰：“禹，吾",{text:"无间然",glossary:"wujianran"},"矣。菲饮食而致孝乎鬼神，恶衣服而致美乎",{text:"黼冕",glossary:"fumian"},"，卑宫室而尽力乎沟洫。禹，吾无间然矣。”"]],note:"「禹，吾无间然矣」——对于禹，我找不出可非议之处（间＝间隙、非议）。「菲饮食而致孝乎鬼神」（自己饮食菲薄而致祭鬼神丰厚），「恶衣服而致美乎黼冕」（自己衣服粗恶而祭服华美），「卑宫室而尽力乎沟洫」（自己宫室低矮而尽力于沟洫水利）。「禹，吾无间然矣」——首尾重叹。"}],o=[{id:"zhide",term:"至德",pinyin:"zhì dé",meaning:"最高的德行。泰伯让国于弟，孔子称其至德。"},{id:"xi-ju",term:"葸",pinyin:"xǐ",meaning:"畏缩、怯懦。慎而无礼则葸：只知谨慎而不知礼，就变成怯懦。"},{id:"jiao",term:"绞",pinyin:"jiǎo",meaning:"急切、尖刻。直而无礼则绞：只知直率而不知礼，就变成尖刻伤人。"},{id:"qiyuzu",term:"启予足",pinyin:"qǐ yǔ zú",meaning:"看看我的脚（是否完好）。古人以为身体发肤受之父母，不敢毁伤，故临终以此自验。"},{id:"baoman",term:"暴慢",pinyin:"bào màn",meaning:"粗暴与怠慢。"},{id:"bibi",term:"鄙倍",pinyin:"bǐ bèi",meaning:"鄙陋与背理。倍：同「背」，违背。"},{id:"fanerbuliao",term:"犯而不校",pinyin:"fàn ér bù jiào",meaning:"被人冒犯也不去计较。校：计较、报复。"},{id:"hongyi",term:"弘毅",pinyin:"hóng yì",meaning:"弘大而刚毅。弘：宽广；毅：坚忍。"},{id:"lin",term:"吝",pinyin:"lìn",meaning:"吝啬、小气。骄且吝：又骄傲又小气。"},{id:"gu-lu",term:"谷",pinyin:"gǔ",meaning:"俸禄（古以谷计禄）。不至于谷：不想到求俸禄。"},{id:"yangyanghu",term:"洋洋乎",pinyin:"yáng yáng hū",meaning:"美盛充满的样子。"},{id:"tong",term:"侗",pinyin:"tóng",meaning:"幼稚无知。"},{id:"kongkong",term:"悾悾",pinyin:"kōng kōng",meaning:"诚恳无知的样子（一说「悾悾」为无能）。"},{id:"dangdanghu",term:"荡荡乎",pinyin:"dàng dàng hū",meaning:"广远浩大、无可名状的样子。"},{id:"wujianran",term:"无间然",pinyin:"wú jiàn rán",meaning:"没有可以非议的地方。间：空隙、非议。"},{id:"fumian",term:"黼冕",pinyin:"fú miǎn",meaning:"祭祀时穿的礼服与礼冠。"},{id:"duyuqin",term:"笃于亲",pinyin:"dǔ yú qīn",meaning:"厚待亲族。笃：厚、真诚。"},{id:"gujiubuyi",term:"故旧不遗",pinyin:"gù jiù bù yí",meaning:"不遗弃旧交老臣。故旧：旧交、老部下。"},{id:"tou",term:"偷",pinyin:"tōu",meaning:"苟且、浇薄。民不偷：民风就不至于浇薄。"},{id:"biandou",term:"笾豆之事",pinyin:"biān dòu zhī shì",meaning:"笾、豆都是祭祀用的礼器；「笾豆之事」指祭祀的具体仪节事务。有司：专管其事的官吏。"}];return(b,n)=>{const r=e("DaoTextReading"),l=e("DaoKeywordCards");return u(),h("div",null,[n[0]||(n[0]=i("",6)),a(r,{colophon:"泰伯第八 · 二十一章",tone:"ink",sections:s,glossary:o,"default-mode":"slips","aria-label":"论语·泰伯 原文"}),n[1]||(n[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"至德",pinyin:["zhì","dé"],meaning:"最高的德行。泰伯让国于弟，孔子称其至德。"},{term:"葸",pinyin:["xǐ"],meaning:"畏缩、怯懦。慎而无礼则葸：只知谨慎而不知礼，就变成怯懦。"},{term:"绞",pinyin:["jiǎo"],meaning:"急切、尖刻。直而无礼则绞：只知直率而不知礼，就变成尖刻伤人。"},{term:"启予足",pinyin:["qǐ","yǔ","zú"],meaning:"看看我的脚（是否完好）。古人以为身体发肤受之父母，不敢毁伤，故临终以此自验。"},{term:"暴慢",pinyin:["bào","màn"],meaning:"粗暴与怠慢。"},{term:"鄙倍",pinyin:["bǐ","bèi"],meaning:"鄙陋与背理。倍：同「背」，违背。"},{term:"犯而不校",pinyin:["fàn","ér","bù","jiào"],meaning:"被人冒犯也不去计较。校：计较、报复。"},{term:"弘毅",pinyin:["hóng","yì"],meaning:"弘大而刚毅。弘：宽广；毅：坚忍。"},{term:"吝",pinyin:["lìn"],meaning:"吝啬、小气。骄且吝：又骄傲又小气。"},{term:"谷",pinyin:["gǔ"],meaning:"俸禄（古以谷计禄）。不至于谷：不想到求俸禄。"},{term:"洋洋乎",pinyin:["yáng","yáng","hū"],meaning:"美盛充满的样子。"},{term:"侗",pinyin:["tóng"],meaning:"幼稚无知。"},{term:"悾悾",pinyin:["kōng","kōng"],meaning:"诚恳无知的样子（一说「悾悾」为无能）。"},{term:"荡荡乎",pinyin:["dàng","dàng","hū"],meaning:"广远浩大、无可名状的样子。"},{term:"无间然",pinyin:["wú","jiàn","rán"],meaning:"没有可以非议的地方。间：空隙、非议。"},{term:"黼冕",pinyin:["fú","miǎn"],meaning:"祭祀时穿的礼服与礼冠。"}]}),n[2]||(n[2]=i("",21))])}}});export{c as __pageData,x as default};
